230	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
231	    @Override
232	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
233	        Collection<Owner> owners;
234	        if (lastName != null) {
235	            owners = this.clinicService.findOwnerByLastName(lastName);
236	        } else {
237	            owners = this.clinicService.findAllOwners();
238	        }
239	        if (owners.isEmpty()) {
240	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
241	        }
242	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
