245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
253	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
254	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
255	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
256	    }
