258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
261	        String telephone = toE164(ownerFieldsDto.getTelephone());
262	        if (telephone == null) {
263	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
264	        }
265	        String email = ownerFieldsDto.getEmail();
266	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
267	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
268	        }
269	        String address = normaliseAddress(ownerFieldsDto.getAddress());
270	        if (address.isEmpty()) {
271	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
272	        }
273	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
274	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
275	        LocalDate registrationDate = toBusinessDay(effectiveDate);
276	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
277	            .map(Owner::getRegistrationDate)
278	            .filter(existing -> existing != null)
279	            .map(OwnerRestControllerV1::toBusinessDay)
280	            .filter(registrationDate::equals)
281	            .count();
282	        if (ownersCreatedThatDay >= 100) {
283	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
284	        }
285	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
286	        long ownersInCity = this.clinicService.findAllOwners().stream()
287	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
288	            .count();
289	        if (ownersInCity >= 50) {
290	            return new ResponseEntity<>(HttpStatus.CONFLICT);
291	        }
292	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
293	            .map(Owner::getTelephone)
294	            .map(OwnerRestControllerV1::toE164)
295	            .filter(existing -> existing != null)
296	            .anyMatch(telephone::equals);
297	        if (telephoneInUse) {
298	            return new ResponseEntity<>(HttpStatus.CONFLICT);
299	        }
300	        if (email != null) {
301	            String emailKey = email.toLowerCase();
302	            boolean emailInUse = this.clinicService.findAllOwners().stream()
303	                .map(Owner::getEmail)
304	                .filter(existing -> existing != null)
305	                .map(String::toLowerCase)
306	                .anyMatch(emailKey::equals);
307	            if (emailInUse) {
308	                return new ResponseEntity<>(HttpStatus.CONFLICT);
309	            }
310	        }
311	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
312	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
313	        String addressKey = address;
314	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
315	            .filter(existing ->
316	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
317	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
318	            .toList();
319	        if (!householdMembers.isEmpty() && !sharesHousehold) {
320	            return new ResponseEntity<>(HttpStatus.CONFLICT);
321	        }
322	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
323	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
324	            .filter(existing ->
325	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
326	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
327	            .count();
328	        HttpHeaders headers = new HttpHeaders();
329	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
330	        owner.setNamesakeCount(namesakeCount);
331	        owner.setAddress(address);
332	        owner.setTelephone(telephone);
333	        owner.setEmail(email == null ? null : email.toLowerCase());
334	        owner.setRegistrationDate(registrationDate);
335	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
336	        if (sharesHousehold && !householdMembers.isEmpty()) {
337	            String householdId = householdId(lastNameKey, addressKey);
338	            owner.setHouseholdId(householdId);
339	            for (Owner member : householdMembers) {
340	                if (member.getHouseholdId() == null) {
341	                    member.setHouseholdId(householdId);
342	                    this.clinicService.saveOwner(member);
343	                }
344	            }
345	        }
346	        this.clinicService.saveOwner(owner);
347	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
348	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
349	            ownerMapper.formatMembershipLevel(owner));
350	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
351	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
352	        headers.setLocation(UriComponentsBuilder.newInstance()
353	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
354	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
355	    }
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Override
359	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
360	        String telephone = toE164(ownerFieldsDto.getTelephone());
361	        if (telephone == null) {
362	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
363	        }
364	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
365	        if (currentOwner == null) {
366	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
367	        }
368	        String email = ownerFieldsDto.getEmail();
369	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
370	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
371	        }
372	        currentOwner.setAddress(ownerFieldsDto.getAddress());
373	        currentOwner.setCity(ownerFieldsDto.getCity());
374	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
375	        currentOwner.setLastName(ownerFieldsDto.getLastName());
376	        currentOwner.setTelephone(telephone);
377	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
378	        this.clinicService.saveOwner(currentOwner);
379	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
380	    }
381	
382	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
383	    @Transactional
384	    @Override
385	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
386	        Owner owner = this.clinicService.findOwnerById(ownerId);
387	        if (owner == null) {
388	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
389	        }
390	        this.clinicService.deleteOwner(owner);
391	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
392	    }
