394	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
395	    @Override
396	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
397	        Owner owner = this.clinicService.findOwnerById(ownerId);
398	        if (owner == null) {
399	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
400	        }
401	        HttpHeaders headers = new HttpHeaders();
402	        Pet pet = petMapper.toPet(petFieldsDto);
403	        owner.setId(ownerId);
404	        pet.setOwner(owner);
405	        pet.getType().setName(null);
406	        this.clinicService.savePet(pet);
407	        PetDto petDto = petMapper.toPetDto(pet);
408	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
409	            .buildAndExpand(pet.getId()).toUri());
410	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
