421	                currentPet.setName(petFieldsDto.getName());
422	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
423	                this.clinicService.savePet(currentPet);
424	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
425	            }
426	        }
427	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
